"""Stable-slot COO path storage with cumulative patching, holes and null slots.

Slots never change count or identity: a `configure` transaction may only replace
the contents of an existing slot, repair a `null` hole, or withdraw a path back
to `null`.  The COO triple `(rows, cols, beta)` is therefore always derived from
the authoritative `slots` table, which keeps sparse holes representable.
"""
from __future__ import annotations

from dataclasses import dataclass, field
from typing import List, Optional, Sequence, Tuple

import numpy as np

from array_utils.cpu.types import BooleanCPUArray, IntegerCPUArray
from array_utils.cpu.wrapper import (
    cpu_bool_zeros,
    cpu_int_array,
    cpu_int_zeros,
)

SlotPath = Optional[Tuple[int, ...]]


@dataclass
class PathProvider:
    """
    Implements the path tensor and availability in a sparse format.

    The tensor `alpha_{ket}` is one when for commodity index `k` the `t`-th path
    crosses edge index `e` and zero otherwise.  It is Boolean valued and very
    sparse, so it is stored in COO format here: `rows[k]` holds edge IDs and
    `cols[k]` the matching slot IDs of commodity `k`.  `beta[k]` is the number
    of non-null slots of commodity `k` (holes included, count is stable).
    """

    shape: Tuple[int, int, int]
    rows: List[IntegerCPUArray]
    cols: List[IntegerCPUArray]
    beta: IntegerCPUArray
    slots: List[List[SlotPath]] = field(default_factory=list)

    # ---------------------------------------------------------------- build
    @classmethod
    def from_slots(cls, slots: Sequence[Sequence[SlotPath]], num_edges: int) -> "PathProvider":
        stored: List[List[SlotPath]] = [
            [None if p is None else tuple(int(e) for e in p) for p in group] for group in slots
        ]
        width = max((len(group) for group in stored), default=0)
        provider = cls((len(stored), num_edges, width), [], [], cpu_int_zeros((len(stored),)), stored)
        for k in range(len(stored)):
            provider.rows.append(cpu_int_zeros((0,)))
            provider.cols.append(cpu_int_zeros((0,)))
            provider._rebuild(k)
        return provider

    def __post_init__(self):
        K = self.shape[0]
        assert len(self.rows) == K
        assert len(self.cols) == K
        assert len(self.beta) == K and self.beta.ndim == 1
        assert len(self.slots) == K
        if K:
            assert self.rows[0].dtype == np.int32
            assert self.cols[0].dtype == np.int32

    # ------------------------------------------------------------ accessors
    @property
    def K(self) -> int:
        return self.shape[0]

    @property
    def num_edges(self) -> int:
        return self.shape[1]

    @property
    def T(self) -> int:
        return self.shape[-1]

    def slot_count(self, k: int) -> int:
        return len(self.slots[k])

    def path(self, k: int, t: int) -> SlotPath:
        return self.slots[k][t]

    def paths(self, k: int) -> List[SlotPath]:
        return list(self.slots[k])

    def clone(self) -> "PathProvider":
        return PathProvider(
            tuple(self.shape),
            [np.array(r, dtype=np.int32, copy=True) for r in self.rows],
            [np.array(c, dtype=np.int32, copy=True) for c in self.cols],
            np.array(self.beta, dtype=np.int32, copy=True),
            [list(group) for group in self.slots],
        )

    # ------------------------------------------------------------- mutation
    def _rebuild(self, k: int) -> None:
        row: List[int] = []
        col: List[int] = []
        count = 0
        for t, path in enumerate(self.slots[k]):
            if path is None:
                continue
            count += 1
            row.extend(path)
            col.extend([t] * len(path))
        self.rows[k] = cpu_int_array(row) if row else cpu_int_zeros((0,))
        self.cols[k] = cpu_int_array(col) if col else cpu_int_zeros((0,))
        self.beta[k] = count

    def update_path(self, k: int, t: int, path: Optional[Sequence[int]]) -> None:
        """Replace slot `t` of commodity `k`, persisting holes and repairs."""
        assert 0 <= t < len(self.slots[k])
        self.slots[k][t] = None if path is None else tuple(int(e) for e in path)
        self._rebuild(k)

    def drop_path(self, k: int, t: int) -> None:
        """Make path index `t` inaccessible to commodity `k` (repaired null)."""
        self.update_path(k, t, None)

    def add_path(self, k: int, path: Sequence[int], t: Optional[int] = None) -> None:
        """Repair a hole (or append when `t` is beyond the stable slot count)."""
        if t is None:
            t = len(self.slots[k])
        if t >= len(self.slots[k]):
            self.slots[k].extend([None] * (t + 1 - len(self.slots[k])))
            self.shape = (self.shape[0], self.shape[1], max(self.T, t + 1))
        self.update_path(k, t, path)

    def reduce_max_path(self, new_T: int) -> None:
        """Shrink the mask in case we have too many paths."""
        assert new_T < self.T
        for k in range(self.K):
            for t in range(new_T, len(self.slots[k])):
                self.slots[k][t] = None
            self._rebuild(k)
        self.shape = (self.shape[0], self.shape[1], new_T)

    # ---------------------------------------------------------- availability
    def availability(self, k: int, live: Sequence[bool]) -> List[bool]:
        """A slot is available iff non-null and every edge on it is live."""
        out = []
        for path in self.slots[k]:
            if path is None:
                out.append(False)
            else:
                out.append(all(live[e] for e in path))
        return out

    def as_array(self, k_start: int = 0, k_end: Optional[int] = None) -> BooleanCPUArray:
        """Return the `alpha` matrix as a gigantic Boolean array."""
        _, N, T = self.shape
        K = self.shape[0] if k_end is None else k_end - k_start
        out = cpu_bool_zeros((K, N, T))
        for k in range(K):
            row = self.rows[k_start + k]
            col = self.cols[k_start + k]
            for i in range(len(row)):
                out[k, int(row[i]), int(col[i])] = True
        return out
